CREATE OR REPLACE FUNCTION public.chantier_autorite_exiger_interne(p_titulaire text, p_pays text, p_ville text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE n text:=public.mon_personnage();a record;d jsonb;
BEGIN
 IF n IS NULL THEN RAISE EXCEPTION 'acteur_non_authentifie' USING ERRCODE='42501';END IF;
 IF p_titulaire LIKE 'orga:%' THEN
  -- Reutiliser la porte de representation existante, pas la presence dans une piece.
  d:=public.organisation_equipement_exiger(substr(p_titulaire,6));
 ELSIF p_titulaire='ville:'||p_pays||':'||p_ville THEN
  SELECT * INTO a FROM public.acteur_poste_courant();
  SELECT poste INTO d FROM public.personnages_donnees WHERE name=n;
  IF a.pays IS DISTINCT FROM p_pays OR a.poste_id IS DISTINCT FROM 'maire' OR a.poste_city IS DISTINCT FROM p_ville
    OR NOT public.poste_est_atteste(n,d,p_pays) THEN RAISE EXCEPTION 'mandat_municipal_requis' USING ERRCODE='42501';END IF;
 ELSIF p_titulaire IS DISTINCT FROM n AND p_titulaire IS DISTINCT FROM 'pj:'||n THEN
  RAISE EXCEPTION 'pas_proprietaire' USING ERRCODE='42501';
 END IF;
END;$function$

CREATE OR REPLACE FUNCTION public.chantier_commande_recu(p_requete text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE n text:=public.mon_personnage();r record;
BEGIN
 IF n IS NULL THEN RETURN jsonb_build_object('ok',false,'raison','acteur_non_authentifie');END IF;
 SELECT * INTO r FROM public.chantier_commandes_recus cr WHERE cr.acteur=n AND cr.requete=p_requete AND cr.personnage_id=(SELECT id FROM public.personnages_donnees WHERE name=n);
 RETURN jsonb_build_object('ok',true,'terminee',FOUND);
END;$function$

CREATE OR REPLACE FUNCTION public.chantier_commande(p_requete text, p_terrain_id text, p_action text, p_parametres jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
#variable_conflict use_variable
DECLARE acteur text:=public.mon_personnage();t record;a record;etat jsonb;ancien_etat jsonb;source jsonb;ch jsonb;pal record;rec record;commande jsonb;resultat jsonb;
 montant numeric;prix jsonb;plan jsonb;lot jsonb;lots jsonb:='[]';s numeric;total numeric:=0;minimum numeric;vus text[]:=ARRAY[]::text[];idlot text;dest text;r jsonb;cle text;v numeric;caisse text;avant text;entrepot text;besoin jsonb;
BEGIN
 IF acteur IS NULL THEN RAISE EXCEPTION 'acteur_non_authentifie' USING ERRCODE='42501';END IF;
 IF p_requete IS NULL OR p_requete !~ '^ch-[A-Za-z0-9-]{8,100}$' OR p_parametres IS NULL OR jsonb_typeof(p_parametres)<>'object' THEN RAISE EXCEPTION 'commande_invalide';END IF;
 SELECT * INTO a FROM public.personnages_donnees WHERE name=acteur FOR UPDATE;
 PERFORM pg_advisory_xact_lock(hashtextextended('chantier:'||acteur||':'||p_requete,0));
 commande:=jsonb_build_object('action',p_action,'parametres',p_parametres);
 SELECT * INTO rec FROM public.chantier_commandes_recus cr WHERE cr.acteur=acteur AND cr.requete=p_requete;
 IF FOUND THEN
  IF rec.personnage_id IS DISTINCT FROM a.id OR rec.terrain_id IS DISTINCT FROM p_terrain_id OR rec.commande<>commande THEN RAISE EXCEPTION 'requete_reutilisee';END IF;
  RETURN rec.resultat||jsonb_build_object('rejeu',true);
 END IF;
 IF coalesce(a.hp,0)<=0 OR coalesce(a.hospitalisation->>'dateFinParis','')>(statement_timestamp() AT TIME ZONE 'Europe/Paris')::date::text THEN RAISE EXCEPTION 'acteur_incapacite';END IF;
 IF EXISTS(SELECT 1 FROM public.detention_active(acteur)) THEN RAISE EXCEPTION 'acteur_detenu';END IF;
 SELECT * INTO t FROM public.terrains_etat WHERE country=a.country AND
  (id=p_terrain_id OR building_id=p_terrain_id AND data::jsonb->>'city'=a.current_city) ORDER BY (id=p_terrain_id) DESC LIMIT 1;
 IF NOT FOUND THEN RAISE EXCEPTION 'terrain_introuvable';END IF;
 ancien_etat:=t.data::jsonb;
 IF p_action<>'travailler' THEN source:=public.chantier_financeur_verrouiller_interne(ancien_etat->>'proprietaire',t.country,ancien_etat->>'city');END IF;
 SELECT * INTO t FROM public.terrains_etat WHERE id=t.id FOR UPDATE;etat:=t.data::jsonb;
 IF etat->>'proprietaire' IS DISTINCT FROM ancien_etat->>'proprietaire' OR etat->>'city' IS DISTINCT FROM ancien_etat->>'city' THEN RAISE EXCEPTION 'titulaire_modifie';END IF;
 IF p_action<>'travailler' THEN PERFORM public.chantier_autorite_exiger_interne(etat->>'proprietaire',t.country,etat->>'city');END IF;
 IF coalesce(etat->>'succession_gel','')<>'' THEN RAISE EXCEPTION 'terrain_gele';END IF;
 ch:=etat->'chantier';
 IF p_action='lancer' THEN
  IF p_parametres-ARRAY['palier','apport']<>'{}' THEN RAISE EXCEPTION 'champs_interdits';END IF;
  IF jsonb_typeof(ch)='object' OR jsonb_typeof(etat->'chantierReamenagement')='object' OR nullif(etat->>'niveau_construction','') IS NOT NULL THEN RAISE EXCEPTION 'chantier_ou_batiment_existant';END IF;
  IF NOT coalesce((etat->>'constructionAutorisee')::boolean,false) OR etat->'permis'->>'palierDemande' IS DISTINCT FROM p_parametres->>'palier' THEN RAISE EXCEPTION 'permis_non_conforme';END IF;
  IF etat->>'pnj' IN('squatter_cool','squatter_agr','cadavre') THEN RAISE EXCEPTION 'occupation_bloquante';END IF;
  SELECT * INTO pal FROM public.chantiers_paliers WHERE palier=p_parametres->>'palier';
  IF NOT FOUND THEN RAISE EXCEPTION 'palier_inconnu';END IF;
  IF p_parametres->>'apport' !~ '^[0-9]+$' OR p_parametres->>'apport' IS NULL THEN RAISE EXCEPTION 'francs_entiers_requis';END IF;
  montant:=(p_parametres->>'apport')::numeric;
  IF montant<pal.apport_minimal OR montant>pal.cout_total THEN RAISE EXCEPTION 'apport_hors_bornes';END IF;
  SELECT jsonb_object_agg(e.cle,ceil(e.prix_base*1.1)) INTO prix FROM public.ressources_economie e WHERE e.cle IN('bois','minerai','metal') AND e.prix_base>=0 AND e.prix_base::text NOT IN('NaN','Infinity','-Infinity');
  IF prix IS NULL OR (SELECT count(*) FROM jsonb_object_keys(prix))<>3 THEN RAISE EXCEPTION 'prix_indisponibles';END IF;
  IF NOT public.chantier_financeur_debiter_interne(source,montant) THEN RAISE EXCEPTION 'fonds_insuffisants';END IF;
  ch:=pal.gabarit||jsonb_build_object('jourDebut',a.day,'jourTraite',(statement_timestamp() AT TIME ZONE 'Europe/Paris')::date::text,'totalVerse',montant,'tresorerie',montant,'prixAchatPJ',prix,'maitreOuvrage',etat->>'proprietaire','planInitialValide',false);
  SELECT building_id INTO entrepot FROM public.entrepots_par_ville WHERE ville=etat->>'city';
  IF entrepot IS NOT NULL THEN
   SELECT jsonb_build_object('bois',bois,'minerai',minerai,'metal',metal) INTO besoin FROM public.chantiers_besoins_jour WHERE position_cycle=1;
   IF besoin IS NULL THEN RAISE EXCEPTION 'besoin_chantier_absent';END IF;
   plan:=public.approvisionner_chantier(acteur,t.country,etat->>'city',entrepot,besoin,coalesce(ch->'stockMateriaux','{}'),(ch->>'tresorerie')::numeric);
   IF NOT coalesce((plan->>'ok')::boolean,false) THEN RAISE EXCEPTION 'approvisionnement_non_confirme';END IF;
   ch:=ch||jsonb_build_object('stockMateriaux',plan->'stockChantier','tresorerie',(ch->>'tresorerie')::numeric-(plan->>'depense')::numeric);
  END IF;
  etat:=etat||jsonb_build_object('chantier',ch);
 ELSIF p_action='verser' THEN
  IF p_parametres-ARRAY['montant']<>'{}' OR jsonb_typeof(ch) IS DISTINCT FROM 'object' OR (ch->>'progressionJours')::numeric>=(ch->>'dureeJours')::numeric THEN RAISE EXCEPTION 'versement_impossible';END IF;
  IF p_parametres->>'montant' !~ '^[0-9]+$' OR p_parametres->>'montant' IS NULL THEN RAISE EXCEPTION 'francs_entiers_requis';END IF;
  montant:=least((p_parametres->>'montant')::numeric,(ch->>'coutTotal')::numeric-(ch->>'totalVerse')::numeric);
  IF montant<=0 THEN RAISE EXCEPTION 'montant_invalide';END IF;
  IF NOT public.chantier_financeur_debiter_interne(source,montant) THEN RAISE EXCEPTION 'fonds_insuffisants';END IF;
  ch:=ch||jsonb_build_object('totalVerse',(ch->>'totalVerse')::numeric+montant,'tresorerie',(ch->>'tresorerie')::numeric+montant);
  etat:=etat||jsonb_build_object('chantier',ch);
 ELSIF p_action='travailler' THEN
  IF p_parametres-ARRAY['heures']<>'{}' OR coalesce(p_parametres->>'heures','') !~ '^[1-9][0-9]*$' THEN RAISE EXCEPTION 'heures_invalides';END IF;
  IF a.current_city IS DISTINCT FROM etat->>'city' OR a.current_building IS DISTINCT FROM t.building_id THEN RAISE EXCEPTION 'pas_sur_place';END IF;
  r:=public.chantier_travailler(acteur,t.country,t.id,(p_parametres->>'heures')::integer);
  IF NOT coalesce((r->>'ok')::boolean,false) THEN RAISE EXCEPTION 'travail_refuse';END IF;
  SELECT data::jsonb INTO etat FROM public.terrains_etat WHERE id=t.id;
  montant:=(r->>'montant')::numeric;
 ELSIF p_action='prix' THEN
  IF p_parametres-ARRAY['prix']<>'{}' OR jsonb_typeof(p_parametres->'prix') IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'prix_invalides';END IF;
  r:=public.chantier_prix_definir(t.id,p_parametres->'prix');
  IF NOT coalesce((r->>'ok')::boolean,false) THEN RAISE EXCEPTION 'prix_invalides';END IF;
  SELECT data::jsonb INTO etat FROM public.terrains_etat WHERE id=t.id;
 ELSIF p_action='plan' THEN
  IF p_parametres-ARRAY['lots','valider']<>'{}' OR jsonb_typeof(p_parametres->'lots') IS DISTINCT FROM 'array' OR jsonb_typeof(p_parametres->'valider') IS DISTINCT FROM 'boolean' THEN RAISE EXCEPTION 'plan_invalide';END IF;
  etat:=public.chantier_plan_enregistrer_interne(etat,p_parametres->'lots',(p_parametres->>'valider')::boolean,t.building_id,t.country,acteur,p_requete,a.day);
 ELSIF p_action='receptionner' THEN
  IF p_parametres<>'{}'::jsonb OR jsonb_typeof(ch) IS DISTINCT FROM 'object' OR NOT coalesce((ch->>'progressionJours')::numeric>=(ch->>'dureeJours')::numeric AND (ch->>'dureeJours')::numeric>0,false) THEN RAISE EXCEPTION 'chantier_non_acheve';END IF;
  IF coalesce((ch->>'totalVerse')::numeric,0)<coalesce((ch->>'coutTotal')::numeric,1) THEN RAISE EXCEPTION 'financement_incomplet';END IF;
  IF a.country IS DISTINCT FROM t.country OR a.current_city IS DISTINCT FROM etat->>'city' OR a.current_building IS DISTINCT FROM t.building_id THEN RAISE EXCEPTION 'pas_sur_place';END IF;
  IF etat->'chantierAcheve'->'reliquats'->>'restitue'='false' THEN RAISE EXCEPTION 'anciens_reliquats_en_attente';END IF;
  plan:=coalesce(etat->'permis'->'decoupageInitial','[]');
  IF jsonb_typeof(plan)<>'array' THEN RAISE EXCEPTION 'plan_invalide';END IF;
  lots:=public.chantier_plan_normaliser_interne(etat,ch->>'niveau',plan);
  IF jsonb_array_length(coalesce(etat->'subdivisions','[]'))>0 THEN RAISE EXCEPTION 'lots_preexistants_a_examiner';END IF;
  montant:=coalesce((ch->>'tresorerie')::numeric,0);
  IF montant<0 OR montant<>trunc(montant) OR montant::text IN('NaN','Infinity','-Infinity') THEN RAISE EXCEPTION 'reliquat_invalide';END IF;
  caisse:=t.country||'_'||(etat->>'city')||'_'||t.building_id;
  IF montant>0 THEN
   avant:=current_setting('rp.caisse_interne',true);PERFORM set_config('rp.caisse_interne','on',true);
   r:=public.caisse_institution_mouvement(caisse,montant,false);PERFORM set_config('rp.caisse_interne',coalesce(avant,''),true);
   IF NOT coalesce((r->>'ok')::boolean,false) THEN RAISE EXCEPTION 'reliquat_caisse_non_confirme';END IF;
  END IF;
  FOREACH cle IN ARRAY ARRAY['bois','minerai','metal'] LOOP
   v:=coalesce((ch->'stockMateriaux'->>cle)::numeric,0);
   IF v<0 OR v<>trunc(v) OR v::text IN('NaN','Infinity','-Infinity') THEN RAISE EXCEPTION 'stock_reliquat_invalide';END IF;
   etat:=jsonb_set(etat,'{stockMateriaux}',coalesce(etat->'stockMateriaux','{}')||jsonb_build_object(cle,coalesce((etat->'stockMateriaux'->>cle)::numeric,0)+v));
  END LOOP;
  IF jsonb_typeof(etat->'chantierAcheve')='object' THEN etat:=etat||jsonb_build_object('chantiersArchives',coalesce(etat->'chantiersArchives','[]')||jsonb_build_array(etat->'chantierAcheve'));END IF;
  etat:=(etat-'chantier')||jsonb_build_object('niveau_construction',ch->>'niveau','subdivisions',lots,'planInitialValide',(coalesce((ch->>'planInitialValide')::boolean,false) OR jsonb_array_length(lots)>0),
   'chantierAcheve',ch||jsonb_build_object('livre',true,'jourLivraison',(statement_timestamp() AT TIME ZONE 'Europe/Paris')::date::text,'tresorerie',0,'stockMateriaux',jsonb_build_object('bois',0,'minerai',0,'metal',0),'reliquats',jsonb_build_object('restitue',true,'beneficiaire',etat->>'proprietaire','caisse',caisse,'tresorerie',montant,'materiaux',ch->'stockMateriaux')));
 ELSE RAISE EXCEPTION 'action_inconnue';
 END IF;
 UPDATE public.terrains_etat SET data=etat::text,niveau_construction=etat->>'niveau_construction',updated_at=now() WHERE id=t.id;
 resultat:=jsonb_build_object('ok',true,'etat',etat,'chantier',etat->'chantier','montant',montant,'pourcentage',CASE WHEN etat ? 'chantier' THEN floor((etat->'chantier'->>'totalVerse')::numeric*100/(etat->'chantier'->>'coutTotal')::numeric) ELSE 100 END);
 INSERT INTO public.chantier_commandes_recus(personnage_id,acteur,requete,terrain_id,commande,resultat) VALUES(a.id,acteur,p_requete,p_terrain_id,commande,resultat);
 RETURN resultat;
EXCEPTION WHEN SQLSTATE 'P0001' OR insufficient_privilege THEN
 IF SQLERRM=ANY(ARRAY['prix_invalides','heures_invalides','travail_refuse','plan_initial_valide','dernier_tiers_requis','reamenagement_payant_requis','local_occupe','batiment_indivisible','document_plan_non_confirme','acteur_detenu','financement_incomplet','acteur_incapacite','acteur_non_authentifie','action_inconnue','anciens_reliquats_en_attente','apport_hors_bornes','approvisionnement_non_confirme','besoin_chantier_absent','champs_interdits','chantier_non_acheve','chantier_ou_batiment_existant','commande_invalide','fonds_insuffisants','francs_entiers_requis','lots_preexistants_a_examiner','mandat_municipal_requis','montant_invalide','occupation_bloquante','palier_inconnu','pas_proprietaire','pas_sur_place','permis_non_conforme','plan_invalide','prix_indisponibles','reliquat_caisse_non_confirme','reliquat_invalide','requete_reutilisee','stock_reliquat_invalide','terrain_gele','terrain_introuvable','titulaire_modifie','versement_impossible','representation_organisation_refusee','etat_financier_non_entier','organisation_absente']) THEN RETURN jsonb_build_object('ok',false,'raison',SQLERRM);END IF;
 RAISE;
END;$function$

CREATE OR REPLACE FUNCTION public.chantier_jour_traiter(p_terrain_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE r record;snapshot jsonb;etat jsonb;ch jsonb;source jsonb;jour text;avant numeric;apres numeric;d numeric;
 besoin jsonb;stock jsonb;plan jsonb;entrepot text;num integer;m text;req numeric;f numeric:=1;cap numeric;faites numeric;heures numeric;cout numeric;gain numeric;plafond numeric;taux numeric;rep jsonb;ancien text;
BEGIN
 IF NOT public.est_appel_serveur() THEN RETURN jsonb_build_object('ok',false,'raison','reserve_au_serveur');END IF;
 SELECT * INTO r FROM public.terrains_etat WHERE id=p_terrain_id;
 IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'raison','terrain_absent');END IF;
 snapshot:=r.data::jsonb;
 IF jsonb_typeof(snapshot->'chantier') IS DISTINCT FROM 'object' THEN RETURN jsonb_build_object('ok',true,'ignore',true);END IF;
 -- Le verrou du financeur precede celui du terrain, comme lancement/ventes/transferts.
 source:=public.chantier_financeur_verrouiller_interne(snapshot->>'proprietaire',r.country,snapshot->>'city');
 SELECT * INTO r FROM public.terrains_etat WHERE id=p_terrain_id FOR UPDATE;etat:=r.data::jsonb;
 IF etat->>'proprietaire' IS DISTINCT FROM snapshot->>'proprietaire' OR etat->>'city' IS DISTINCT FROM snapshot->>'city' THEN
  RETURN jsonb_build_object('ok',false,'raison','titulaire_modifie');END IF;
 ch:=etat->'chantier';jour:=(statement_timestamp() AT TIME ZONE 'Europe/Paris')::date::text;
 IF coalesce(etat->>'succession_gel','')<>'' THEN RETURN jsonb_build_object('ok',true,'ignore',true,'raison','terrain_gele');END IF;
 IF ch->>'type' IS DISTINCT FROM 'construction' THEN RETURN jsonb_build_object('ok',false,'raison','chantier_historique_a_examiner');END IF;
 IF ch->>'jourTraite'=jour THEN RETURN jsonb_build_object('ok',true,'rejeu',true,'etat',etat);END IF;
 avant:=(ch->>'progressionJours')::numeric;d:=(ch->>'dureeJours')::numeric;
 IF avant IS NULL OR avant<0 OR d IS NULL OR d<=0 OR d<>trunc(d) THEN RAISE EXCEPTION 'dimensionnement_chantier_invalide';END IF;
 IF avant<d THEN
  ch:=public.chantier_appel_fonds_interne(ch,source);
  IF ch->>'arrete' IS DISTINCT FROM 'financement' THEN
   num:=floor(avant)::integer+1;
   SELECT jsonb_build_object('bois',bois,'minerai',minerai,'metal',metal) INTO besoin FROM public.chantiers_besoins_jour
    WHERE position_cycle=((num-1)%(SELECT count(*) FROM public.chantiers_besoins_jour))+1;
   IF besoin IS NULL THEN RAISE EXCEPTION 'besoin_chantier_absent';END IF;
   SELECT building_id INTO entrepot FROM public.entrepots_par_ville WHERE ville=etat->>'city';
   stock:=coalesce(ch->'stockMateriaux','{}');
   IF entrepot IS NOT NULL THEN
    plan:=public.approvisionner_chantier(source->>'destinataire',r.country,etat->>'city',entrepot,besoin,stock,coalesce((ch->>'tresorerie')::numeric,0));
    IF NOT coalesce((plan->>'ok')::boolean,false) THEN RAISE EXCEPTION 'approvisionnement_non_confirme';END IF;
    stock:=plan->'stockChantier';ch:=ch||jsonb_build_object('tresorerie',(ch->>'tresorerie')::numeric-(plan->>'depense')::numeric);
   END IF;
   FOREACH m IN ARRAY ARRAY['bois','minerai','metal'] LOOP
    req:=(besoin->>m)::numeric;
    IF req>0 THEN f:=least(f,greatest(0,coalesce((stock->>m)::numeric,0))/req);END IF;
   END LOOP;
   SELECT valeur INTO taux FROM public.entreprises_constantes WHERE cle='chantier_taux_horaire';
   IF taux IS NULL OR taux<=0 THEN RAISE EXCEPTION 'taux_chantier_indisponible';END IF;
   cap:=(ch->>'coutTravail')::numeric/taux/d;faites:=coalesce((ch->>'heuresFaites')::numeric,0);
   IF cap IS NULL OR cap<=0 OR faites<0 OR faites>cap THEN RAISE EXCEPTION 'capacite_travail_invalide';END IF;
   plafond:=CASE WHEN (ch->>'totalVerse')::numeric>=(ch->>'coutTotal')::numeric THEN d
     WHEN (ch->>'totalVerse')::numeric>=ceil((ch->>'coutTotal')::numeric*.7) THEN d*2/3 ELSE d/3 END;
   heures:=greatest(0,least(floor(cap*least(f,d-avant,plafond-avant))-faites,floor((ch->>'tresorerie')::numeric/taux)));cout:=heures*taux;
   IF cout>0 THEN
    ancien:=current_setting('rp.caisse_interne',true);PERFORM set_config('rp.caisse_interne','on',true);
    rep:=public.caisse_institution_mouvement(r.country||'_gouvernement-min_fin',cout,true);
    PERFORM set_config('rp.caisse_interne',coalesce(ancien,''),true);
    IF NOT coalesce((rep->>'ok')::boolean,false) THEN RAISE EXCEPTION 'remuneration_pnj_non_confirmee';END IF;
   END IF;
   gain:=least(1,f,(faites+heures)/cap,d-avant);
   gain:=greatest(0,least(gain,plafond-avant));apres:=avant+gain;
   FOREACH m IN ARRAY ARRAY['bois','minerai','metal'] LOOP
    stock:=jsonb_set(stock,ARRAY[m],to_jsonb(greatest(0,coalesce((stock->>m)::numeric,0)-floor((besoin->>m)::numeric*gain))));
   END LOOP;
   ch:=ch||jsonb_build_object('progressionJours',apres,'tresorerie',(ch->>'tresorerie')::numeric-cout,'stockMateriaux',stock,'heuresFaites',0,'arrete',CASE WHEN gain=0 THEN 'penurie_materiaux' ELSE NULL END,
    'evenements',coalesce(ch->'evenements','[]')||jsonb_build_array(jsonb_build_object('cle','journee','date',jour,'avance',gain,'heuresPNJ',heures,'coutPNJ',cout,'achats',plan->'achats')));
   -- Un seuil atteint aujourd'hui appelle immediatement la tranche suivante, sans avancer le temps utile si refus.
   IF apres<d THEN ch:=public.chantier_appel_fonds_interne(ch,source);END IF;
  END IF;
 END IF;
 IF (ch->>'progressionJours')::numeric>=d THEN
  IF NOT coalesce((ch->>'attenteReception')::boolean,false) AND nullif(source->>'destinataire','') IS NOT NULL THEN
   rep:=public.mail_systeme_poser_interne('Chef de Chantier',source->>'destinataire','Chantier acheve — reception sur place','Les travaux sont acheves. Venez sur place pour receptionner le batiment et ouvrir ses locaux.');
   IF NOT coalesce((rep->>'ok')::boolean,false) THEN ch:=ch||jsonb_build_object('notificationEchec',rep);END IF;
  END IF;
  ch:=ch||jsonb_build_object('attenteReception',true,'arrete',null);
 END IF;
 ch:=ch||jsonb_build_object('jourTraite',jour);
 etat:=etat||jsonb_build_object('chantier',ch);
 UPDATE public.terrains_etat SET data=etat::text,updated_at=now() WHERE id=p_terrain_id;
 RETURN jsonb_build_object('ok',true,'etat',etat,'attenteReception',coalesce((ch->>'attenteReception')::boolean,false),'avance',coalesce(gain,0));
END;$function$

CREATE OR REPLACE FUNCTION public.compromis_expire_resoudre(p_type text, p_cible text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_type text := lower(btrim(coalesce(p_type,''))); v_data jsonb;
  v_pays text; v_bat text; v_prefixe text; v_expire bigint;
  v_ms bigint := (extract(epoch from now())*1000)::bigint;
  v_pret jsonb; v_refus boolean := false; v_gele boolean := false; v_existe boolean;
  v_detail text[] := ARRAY[]::text[]; v_montant numeric; v_arg numeric;
  v_acompte numeric; v_par text; v_perm text;
  v_jour text := to_char((now() AT TIME ZONE 'Europe/Paris')::date, 'YYYY-MM-DD');
BEGIN
  -- FAIL-CLOSED : un type ou une cible absents LEVENT. Rendre un verdict voudrait dire
  -- « rien a resoudre », et le cron reposerait un drapeau qu'il n'a pas gagne.
  IF v_type NOT IN ('terrain','entreprise') THEN
    RAISE EXCEPTION 'compromis_expire_resoudre : type inconnu « % »', p_type; END IF;
  IF btrim(coalesce(p_cible,'')) = '' THEN
    RAISE EXCEPTION 'compromis_expire_resoudre : la cible est obligatoire'; END IF;

  -- LE VERROU SUR LE BIEN est ce qui serialise deux passes simultanees.
  IF v_type = 'terrain' THEN
    SELECT t.data::jsonb, t.country, t.building_id INTO v_data, v_pays, v_bat
      FROM public.terrains_etat t WHERE t.id = p_cible FOR UPDATE;
    v_prefixe := 'compromis-';
  ELSE
    -- Le pays d'une entreprise : son blob d'abord, sinon le DEUXIEME segment de l'identifiant
    -- (« <type>-<pays>-<ville> »). C'est exactement ce que lisait `split('-').slice(1)[0]`.
    SELECT e.data,
           nullif(coalesce(e.data->>'country', split_part(coalesce(e.data->>'id', e.id),'-',2)),''), e.id
      INTO v_data, v_pays, v_bat FROM public.entreprises e WHERE e.id = p_cible FOR UPDATE;
    v_prefixe := 'compromis-entreprise-';
  END IF;
  IF v_data IS NULL THEN RETURN jsonb_build_object('ok', false, 'action','non_applicable'); END IF;
  -- Un bien Helvetia garde sa propre RPC : on ne reimplemente pas sa decision ici.
  IF v_type = 'terrain' AND (v_data->>'proprietaire') = 'Helvetia' THEN
    RETURN jsonb_build_object('ok', false, 'action','helvetia'); END IF;
  IF coalesce((v_data->>'compromis')::boolean, false) IS NOT TRUE
     OR (v_data->>'compromisExpireAt') IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'action','non_applicable'); END IF;
  v_expire := (v_data->>'compromisExpireAt')::bigint;
  IF v_expire > v_ms THEN RETURN jsonb_build_object('ok', false, 'action','pas_encore_expire'); END IF;

  -- UN PRET DEJA ACCORDE GELE LE COMPROMIS (correctif du 10 aout 2026) : sans cette garde, la
  -- meme ligne se ferait perdre son acompte a chaque passage du cron, chaque nuit.
  v_pret := v_data->'pretDemande';
  IF jsonb_typeof(v_pret) = 'object' AND v_pret->>'statut' = 'accorde' THEN
    RETURN jsonb_build_object('ok', true, 'action','pret_accorde_compromis_gele'); END IF;

  -- PERMIS DU MAIRE : terrain seulement. Pas de reponse = positif, maintenant.
  IF v_type = 'terrain' THEN
    v_perm := v_data #>> '{permis,statut}';
    IF v_perm = 'attente_validation' THEN
      v_data := jsonb_set(jsonb_set(v_data, '{permis,statut}', '"valide"'),
                          '{permis,autoValide}', 'true');
      v_data := jsonb_set(v_data, '{constructionAutorisee}', 'true', true);
      v_detail := array_append(v_detail, 'permis validé (sans réponse du maire)');
    ELSIF v_perm = 'valide' THEN
      v_data := jsonb_set(v_data, '{constructionAutorisee}', 'true', true);
      v_detail := array_append(v_detail, 'permis validé par le maire');
    ELSIF v_perm = 'refuse' THEN
      v_refus := true; v_detail := array_append(v_detail, 'permis refusé par le maire');
    END IF;
  END IF;

  -- LE TIRAGE DU PRET EST ICI, pas chez l'appelant : un rejeu ne peut plus le rejouer.
  IF jsonb_typeof(v_pret) = 'object' AND v_pret->>'statut' = 'attente_validation' THEN
    v_montant := coalesce((v_pret->>'montant')::numeric, 0);
    SELECT true, coalesce(arg,0) INTO v_existe, v_arg FROM public.personnages
     WHERE name = v_pret->>'demandeur' FOR UPDATE;
    v_arg := coalesce(v_arg, 0);
    IF v_arg >= v_montant * 0.10 OR random() < 0.5 THEN
      v_data := jsonb_set(v_data, '{pretDemande,statut}', '"accorde"');
      IF coalesce(v_existe, false) THEN
        UPDATE public.personnages SET arg = coalesce(arg,0) + v_montant
         WHERE name = v_pret->>'demandeur';
        INSERT INTO public.prets (id, emprunteur, country, building_id, type_banque,
            montant_initial, montant_restant, duree_jours, mensualite, jours_impayes, statut)
        VALUES ('pret-' || v_type || '-' || p_cible || '-' || v_jour, v_pret->>'demandeur',
            v_pays, v_bat, 'nationale', v_montant, (v_pret->>'montantTotal')::numeric,
            (v_pret->>'duree')::integer, (v_pret->>'mensualite')::numeric, 0, 'en_cours')
        ON CONFLICT (id) DO NOTHING;
      END IF;
      v_detail := array_append(v_detail, 'prêt accordé (+' || v_montant::text || ' FR virés)');
      v_gele := true;
    ELSE
      v_data := jsonb_set(v_data, '{pretDemande,statut}', '"refuse"');
      v_refus := true; v_detail := array_append(v_detail, 'prêt refusé par la banque');
    END IF;
  END IF;

  -- Pret accorde a l'instant, aucune autre clause refusee : le compromis reste actif, ni
  -- rembourse ni perdu -- le joueur finalisera plus tard avec l'argent prete.
  IF v_gele AND NOT v_refus THEN
    IF v_type = 'terrain' THEN
      UPDATE public.terrains_etat SET data = v_data::text, updated_at = now() WHERE id = p_cible;
    ELSE
      UPDATE public.entreprises SET data = v_data, updated_at = now() WHERE id = p_cible;
    END IF;
    RETURN jsonb_build_object('ok', true, 'action','pret_en_attente_finalisation',
                              'detail', array_to_string(v_detail,' · '));
  END IF;

  v_acompte := coalesce((v_data->>'acompte')::numeric, 0);
  v_par := v_data->>'compromisPar';
  IF v_refus AND v_par IS NOT NULL AND v_acompte > 0 THEN
    UPDATE public.personnages SET arg = coalesce(arg,0) + v_acompte WHERE name = v_par;
    v_detail := array_append(v_detail, 'acompte remboursé (' || v_acompte::text || ' FR)');
  ELSE
    v_detail := array_append(v_detail, 'acompte perdu (' || v_acompte::text || ' FR)');
  END IF;

  INSERT INTO public.compromis_historique (id, country, building_id, demandeur, resultat, detail)
  VALUES (v_prefixe || p_cible || '-' || v_jour, v_pays, v_bat, coalesce(v_par,'inconnu'),
          CASE WHEN v_refus THEN 'rembourse' ELSE 'perdu' END,
          coalesce(nullif(array_to_string(v_detail,' · '),''),
                   CASE WHEN v_type='entreprise'
                        THEN 'compromis de rachat d''entreprise expiré sans finalisation'
                        ELSE '' END))
  ON CONFLICT (id) DO NOTHING;

  -- `pretDemande` est efface aussi (10 aout 2026) : un {statut:'refuse'} laisse accroche aurait
  -- bloque a tort le pretOk d'un futur compromis n'ayant rien demande.
  v_data := v_data - 'compromis' - 'compromisPar' - 'acompte' - 'compromisAt'
                   - 'compromisExpireAt' - 'pretDemande';
  IF v_type = 'terrain' THEN
    UPDATE public.terrains_etat SET data = v_data::text, updated_at = now() WHERE id = p_cible;
  ELSE
    UPDATE public.entreprises SET data = v_data, updated_at = now() WHERE id = p_cible;
  END IF;

  RETURN jsonb_build_object('ok', true,
    'action', CASE WHEN v_refus THEN 'rembourse' ELSE 'perdu' END,
    'acompte', v_acompte, 'detail', array_to_string(v_detail,' · '));
END; $function$

CREATE OR REPLACE FUNCTION public.fermeture_definir_date_universelle()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.duree_jours IS NULL OR NEW.duree_jours < 1 OR NEW.duree_jours > 36500 THEN
    RAISE EXCEPTION 'Fermeture : duree_jours obligatoire (1..36500)';
  END IF;
  -- La base décide de la date, pas le navigateur ni le compteur individuel.
  NEW.date_fin_universelle := (now() AT TIME ZONE 'Europe/Paris')::date + NEW.duree_jours;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.helvetia_debiter_fonds_ordinaires(p_personnage text, p_montant numeric, p_priorite text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_liquide numeric; v_arg numeric; v_solde numeric;
  v_preleve_liquide numeric; v_preleve_national numeric;
BEGIN
  IF p_priorite NOT IN ('liquide','nationale') OR p_priorite IS NULL THEN RAISE EXCEPTION 'priorite_invalide'; END IF;
  IF p_montant IS NULL OR p_montant <= 0 THEN RETURN true; END IF;

  SELECT COALESCE(liquide,0), COALESCE(arg,0) INTO v_liquide, v_arg
    FROM public.personnages_donnees WHERE name = p_personnage FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Personnage introuvable'; END IF;

  SELECT COALESCE(solde,0) INTO v_solde FROM public.comptes_bancaires
   WHERE personnage = p_personnage AND banque = 'nationale' FOR UPDATE;

  -- Les circuits historiques conservent leur priorite liquide et leur representation.
  -- La construction requiert des francs entiers : ne jamais arrondir un solde historique.
  IF p_priorite='nationale' AND (p_montant<>trunc(p_montant) OR v_liquide<>trunc(v_liquide)
      OR coalesce(v_solde,0)<>trunc(coalesce(v_solde,0)) OR v_liquide<0 OR coalesce(v_solde,0)<0) THEN
    RAISE EXCEPTION 'etat_financier_non_entier'; END IF;
  IF (v_liquide + COALESCE(v_solde,0)) < p_montant THEN RETURN false; END IF;
  IF p_priorite='nationale' THEN
    v_preleve_national:=LEAST(coalesce(v_solde,0),p_montant);
    v_preleve_liquide:=p_montant-v_preleve_national;
  ELSE
    v_preleve_liquide:=LEAST(v_liquide,p_montant);
    v_preleve_national:=p_montant-v_preleve_liquide;
  END IF;

  UPDATE public.personnages_donnees
     SET liquide = v_liquide - v_preleve_liquide,
         arg = GREATEST(0, v_arg - p_montant),
         updated_at = now()
   WHERE name = p_personnage;

  IF v_preleve_national > 0 THEN
    UPDATE public.comptes_bancaires SET solde = solde - v_preleve_national, updated_at = now()
     WHERE personnage = p_personnage AND banque = 'nationale';
  END IF;

  RETURN true;
END; $function$

CREATE OR REPLACE FUNCTION public.payer_ordre(p_acteur text, p_fn text DEFAULT NULL::text, p_pa integer DEFAULT 0, p_cost integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_fn text := coalesce(nullif(btrim(coalesce(p_fn,'')), ''), '(non transmis)');
  v_connu boolean; v_valide boolean;
  v_pa integer; v_liquide numeric; v_arg numeric;
  v_compte_id text; v_solde numeric := 0;
  v_pris_liquide numeric; v_pris_national numeric;
  v_memorable record; v_pays text;
BEGIN
  IF v_fn = 'deposer_demande_permis' AND NOT EXISTS (
    SELECT 1 FROM public.permis_transactions_internes WHERE transaction_id=txid_current() AND acteur=auth.uid()
  ) THEN RETURN jsonb_build_object('ok',false,'raison','commande_versionnee_requise'); END IF;
  PERFORM public.exiger_acteur(p_acteur);
  IF coalesce(p_pa, 0) < 0 OR coalesce(p_cost, 0) < 0 THEN
    RETURN jsonb_build_object('ok', false, 'raison', 'montant_negatif');
  END IF;

  SELECT EXISTS (SELECT 1 FROM public.ordres_couts o WHERE o.fn = v_fn) INTO v_connu;

  IF NOT v_connu THEN
    INSERT INTO public.ordres_couts_inconnus (fn, pa, cost)
    VALUES (v_fn, coalesce(p_pa,0), coalesce(p_cost,0))
    ON CONFLICT (fn) DO UPDATE SET occurrences = public.ordres_couts_inconnus.occurrences + 1;
    RETURN jsonb_build_object('ok', false, 'raison', 'ordre_inconnu', 'fn', v_fn);
  END IF;

  SELECT EXISTS (SELECT 1 FROM public.ordres_couts o
                 WHERE o.fn = v_fn AND o.pa = coalesce(p_pa,0) AND o.cost = coalesce(p_cost,0))
    INTO v_valide;
  IF NOT v_valide THEN
    INSERT INTO public.ordres_couts_ecarts (fn, pa, cost)
    VALUES (v_fn, coalesce(p_pa,0), coalesce(p_cost,0))
    ON CONFLICT (fn, pa, cost)
      DO UPDATE SET occurrences = public.ordres_couts_ecarts.occurrences + 1, vu_le = now();
    RETURN jsonb_build_object('ok', false, 'raison', 'cout_non_declare',
                              'fn', v_fn, 'pa', p_pa, 'cost', p_cost);
  END IF;

  SELECT pa, liquide, arg INTO v_pa, v_liquide, v_arg
  FROM public.personnages_donnees WHERE name = p_acteur FOR UPDATE;
  IF v_pa IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'raison', 'personnage_introuvable');
  END IF;

  SELECT id, solde INTO v_compte_id, v_solde FROM public.comptes_bancaires
  WHERE personnage = p_acteur AND banque = 'nationale' FOR UPDATE;
  v_solde := coalesce(v_solde, 0);

  IF v_pa < coalesce(p_pa, 0) THEN
    RETURN jsonb_build_object('ok', false, 'raison', 'pa_insuffisants', 'pa_reel', v_pa);
  END IF;
  IF coalesce(v_liquide,0) + v_solde < coalesce(p_cost, 0) THEN
    RETURN jsonb_build_object('ok', false, 'raison', 'fonds_insuffisants',
                              'disponible', coalesce(v_liquide,0) + v_solde);
  END IF;

  v_pris_liquide := least(coalesce(v_liquide,0), coalesce(p_cost,0));
  v_pris_national := coalesce(p_cost,0) - v_pris_liquide;

  UPDATE public.personnages_donnees
     SET pa = v_pa - coalesce(p_pa,0),
         liquide = coalesce(v_liquide,0) - v_pris_liquide,
         arg = coalesce(v_arg,0) - coalesce(p_cost,0)
   WHERE name = p_acteur;

  IF v_pris_national > 0 AND v_compte_id IS NOT NULL THEN
    UPDATE public.comptes_bancaires SET solde = solde - v_pris_national,
           updated_at = now() WHERE id = v_compte_id;
  END IF;

  -- LA MEMOIRE DES MANDATS (11 octobre 2026). Apres le prelevement, donc sur un fait accompli, et
  -- seulement si le triplet figure au registre des actes memorables. `presidence_memoire_noter`
  -- verifie elle-meme que l'acteur est bien le President en exercice : si c'est un ministre qui
  -- tient la conference de presse, rien n'est ecrit. Le registre ne contient AUCUN panneau a
  -- (0 PA, 0 FR) -- ouvrir une fenetre n'est pas un acte.
  SELECT * INTO v_memorable FROM public.presidence_memoire_ordres
   WHERE fn = v_fn AND pa = coalesce(p_pa,0) AND cost = coalesce(p_cost,0);
  IF FOUND THEN
    SELECT country INTO v_pays FROM public.personnages_donnees WHERE name = p_acteur;
    PERFORM public.presidence_memoire_noter(
      v_pays, 'reaction', 'ordre_presidentiel', v_memorable.sujet,
      jsonb_build_object('ordre', v_fn, 'pa', coalesce(p_pa,0), 'cout', coalesce(p_cost,0)),
      p_acteur);
  END IF;

  RETURN jsonb_build_object(
    'ok', true, 'pa', v_pa - coalesce(p_pa,0),
    'liquide', coalesce(v_liquide,0) - v_pris_liquide,
    'arg', coalesce(v_arg,0) - coalesce(p_cost,0),
    'solde_national', v_solde - v_pris_national,
    'pa_preleves', coalesce(p_pa,0), 'montant_preleve', coalesce(p_cost,0));
END;
$function$

CREATE OR REPLACE FUNCTION public.prelever_loyer_bail(p_bail_id text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_bail        locations_actives%ROWTYPE;
  v_data        jsonb;
  v_locataire   text;
  v_prix        numeric;
  v_dest        jsonb;
  v_dest_type   text;
  v_pays        text;
  v_ville       text;
  v_building    text;
  v_arg         numeric;
  v_liquide_loyer numeric;
  v_disponible_bancaire numeric;
  v_debit_banque numeric;
  v_debit_liquide numeric;
  v_jour        text := to_char(now() AT TIME ZONE 'Europe/Paris', 'YYYY-MM-DD');
  v_cle         text;
  v_titulaire   text;
  v_orga_id     text;
  v_orga_data   text;
  v_maj         integer;
  v_rec         jsonb;
  -- L'ardoise de l'impaye, desormais calculee ET posee ici : voir le bloc de la
  -- branche « expulsion_requise ».
  v_imp         jsonb;
  v_avise       boolean;
BEGIN
  SELECT *
  INTO v_bail
  FROM locations_actives
  WHERE id = p_bail_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN 'bail_absent';
  END IF;

  v_data      := v_bail.data;
  v_locataire := v_data ->> 'locataire';
  v_prix      := COALESCE((v_data ->> 'prix')::numeric, 0);

  -- Anti-rejeu : un seul prélèvement par bail et par jour réel.
  IF (v_data ->> 'jourPaiement') = v_jour THEN
    RETURN 'deja_preleve';
  END IF;

  -- Usages sans loyer réel.
  IF v_prix <= 0
     OR (v_data ->> 'chambreClinique') = 'true'
     OR v_locataire IS NULL
  THEN
    UPDATE locations_actives
    SET data = v_data || jsonb_build_object('jourPaiement', v_jour)
    WHERE id = p_bail_id;

    RETURN 'ignore_sans_loyer';
  END IF;

  -- DESTINATION ATTESTEE (20 septembre 2026). Elle n'est plus lue dans le bail --
  -- ecriture directe falsifiable -- mais DERIVEE du local, par la meme regle que le
  -- client (destinationLoyerPourLocal). Le champ destinationLoyer du bail n'est plus
  -- qu'informatif. Fail-closed inchange : pas de destination -> pas de mouvement.
  v_dest := public.bail_destination_attestee(v_data);
  IF v_dest IS NULL THEN
    UPDATE locations_actives
    SET data = v_data || jsonb_build_object('jourPaiement', v_jour)
    WHERE id = p_bail_id;
    RETURN 'ignore_sans_loyer';
  END IF;

  IF v_dest IS NULL OR jsonb_typeof(v_dest) = 'null' THEN
    UPDATE locations_actives
    SET data = v_data || jsonb_build_object('jourPaiement', v_jour)
    WHERE id = p_bail_id;

    RETURN 'ignore_sans_loyer';
  END IF;

  v_dest_type := v_dest ->> 'type';

  -- Verrou du locataire.
  SELECT arg
  INTO v_arg
  FROM personnages
  WHERE name = v_locataire
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN 'locataire_absent';
  END IF;

  SELECT coalesce(liquide,0) INTO v_liquide_loyer
     FROM public.personnages_donnees WHERE name=v_locataire FOR UPDATE;
  SELECT coalesce(sum(greatest(solde,0)),0) INTO v_disponible_bancaire
     FROM public.comptes_bancaires WHERE personnage=v_locataire AND banque='nationale';
  -- Impayé.
  IF COALESCE(v_arg, 0) < v_prix OR coalesce(v_liquide_loyer,0)+v_disponible_bancaire < v_prix THEN
    IF COALESCE((v_data ->> 'avertissement')::boolean, false) THEN
      -- ARDOISE ATOMIQUE (chantier 6, 9 octobre 2026). Cette branche etait LA SEULE sortie
      -- a effet a ne pas poser jourPaiement : un rejeu du cron la meme nuit rendait de
      -- nouveau « expulsion_requise », et l'appelant rajoutait un jour et un loyer a
      -- l'ardoise. La dette DOUBLAIT a chaque passe.
      --
      -- Poser le marqueur ne suffisait pas : l'appelant reecrivait le blob entier depuis
      -- une lecture ANTERIEURE a cet appel, et effacait donc le marqueur dans la foulee.
      -- Le calcul de l'ardoise descend ici, ou il devient atomique avec sa revendication :
      -- une RPC est une seule transaction, et v_data a ete lu FOR UPDATE.
      --
      -- La regle, elle, ne change pas (arbitrage du 8 septembre 2026) : aucune expulsion
      -- automatique, un impaye est un FAIT qu'on chiffre et qu'on conserve, et un seul
      -- avis a l'ouverture de l'ardoise. Aucun argent ne bouge : le loyer reste du.
      v_imp := CASE WHEN jsonb_typeof(v_data -> 'impaye') = 'object'
                    THEN v_data -> 'impaye' ELSE '{}'::jsonb END;
      v_avise := COALESCE((v_imp ->> 'avisEnvoye')::boolean, false);
      UPDATE locations_actives
         SET data = v_data || jsonb_build_object(
               'jourPaiement', v_jour,
               'impaye', jsonb_build_object(
                  'depuis',     COALESCE(v_imp ->> 'depuis', v_jour),
                  'jours',      COALESCE((v_imp ->> 'jours')::numeric, 0) + 1,
                  'montantDu',  COALESCE((v_imp ->> 'montantDu')::numeric, 0) + v_prix,
                  'avisEnvoye', true))
       WHERE id = p_bail_id;
      -- Deux verdicts distincts, parce que l'appelant n'a plus qu'une chose a faire et
      -- qu'elle depend de celui-ci : poster l'avis UNE fois, a l'ouverture.
      IF v_avise THEN
        RETURN 'expulsion_requise_deja_avise';
      END IF;
      RETURN 'expulsion_requise';
    END IF;

    UPDATE locations_actives
    SET data = v_data
      || jsonb_build_object(
           'avertissement', true,
           'jourPaiement', v_jour
         )
    WHERE id = p_bail_id;

    RETURN 'avertissement';
  END IF;

  -- Crédit de la destination.
  IF v_dest_type = 'municipal' THEN

    v_pays  := COALESCE(v_dest ->> 'pays',  v_data ->> 'country');
    v_ville := COALESCE(v_dest ->> 'ville', v_data ->> 'city');

    v_rec := public.recette_municipale(v_pays, v_ville, v_prix, 'loyer');
    IF NOT COALESCE((v_rec ->> 'ok')::boolean, false) THEN
      RAISE EXCEPTION 'destination_introuvable';
    END IF;

  ELSIF v_dest_type = 'titulaire_murs' THEN

    -- Le titulaire explicite n'est PLUS lu : c'etait la porte par laquelle un bail
    -- falsifie redirigeait le loyer. Le proprietaire ACTUEL fait foi, toujours.
    v_titulaire := NULL;

    IF v_titulaire IS NULL OR v_titulaire = '' THEN
      SELECT (data::jsonb ->> 'proprietaire')
      INTO v_titulaire
      FROM terrains_etat
      WHERE country = (v_data ->> 'country')
        AND building_id = (v_data ->> 'buildingId');
    END IF;

    IF v_titulaire IS NULL OR v_titulaire = '' THEN
      RAISE EXCEPTION 'destination_introuvable';
    END IF;

    -- Organisation propriétaire.
    IF left(v_titulaire, 5) = 'orga:' THEN

      v_orga_id := substr(v_titulaire, 6);

      IF v_orga_id = '' THEN
        RAISE EXCEPTION 'destination_introuvable';
      END IF;

      SELECT data
      INTO v_orga_data
      FROM organisations
      WHERE id = v_orga_id
      FOR UPDATE;

      IF NOT FOUND THEN
        RAISE EXCEPTION 'destination_introuvable';
      END IF;

      IF v_orga_data IS NULL OR btrim(v_orga_data) = '' THEN
        RAISE EXCEPTION 'destination_introuvable';
      END IF;

      UPDATE organisations
      SET data = jsonb_set(
                   v_orga_data::jsonb,
                   '{caisse}',
                   to_jsonb(
                     COALESCE(
                       (v_orga_data::jsonb ->> 'caisse')::numeric,
                       0
                     ) + v_prix
                   )
                 )::text
      WHERE id = v_orga_id;

    ELSE

      -- PJ propriétaire, avec compatibilité ancien format nom brut.
      IF left(v_titulaire, 3) = 'pj:' THEN
        v_titulaire := substr(v_titulaire, 4);
      END IF;

      UPDATE personnages
      SET arg = COALESCE(arg, 0) + v_prix
      WHERE name = v_titulaire;

      GET DIAGNOSTICS v_maj = ROW_COUNT;

      IF v_maj = 0 THEN
        RAISE EXCEPTION 'destination_introuvable';
      END IF;

    END IF;

  ELSIF v_dest_type = 'caisse_batiment' THEN

    v_building := COALESCE(
      v_dest ->> 'buildingId',
      v_data ->> 'buildingId'
    );

    v_cle := (v_data ->> 'country') || '_' || v_building;

    UPDATE caisses_batiments
    SET data = jsonb_set(
                 COALESCE(data, '{}'::jsonb),
                 '{solde}',
                 to_jsonb(
                   COALESCE((data ->> 'solde')::numeric, 0) + v_prix
                 )
               ),
        updated_at = now()
    WHERE id = v_cle;

    GET DIAGNOSTICS v_maj = ROW_COUNT;

    IF v_maj = 0 THEN
      INSERT INTO caisses_batiments (id, data, updated_at)
      VALUES (
        v_cle,
        jsonb_build_object('solde', v_prix),
        now()
      );
    END IF;

  ELSE
    RAISE EXCEPTION 'destination_introuvable';
  END IF;

  -- Débit atomique des avoirs réels, priorité au compte national.
  v_debit_banque:=least(v_disponible_bancaire,v_prix);
  v_debit_liquide:=v_prix-v_debit_banque;
  UPDATE public.comptes_bancaires
     SET solde=solde-v_debit_banque,updated_at=now()
   WHERE personnage=v_locataire AND banque='nationale' AND solde>=v_debit_banque;
  IF v_debit_banque>0 AND NOT FOUND THEN RAISE EXCEPTION 'compte_bancaire_modifie'; END IF;
  UPDATE public.personnages_donnees
     SET arg=arg-v_prix,liquide=liquide-v_debit_liquide,updated_at=now()
   WHERE name=v_locataire AND liquide>=v_debit_liquide;
  IF NOT FOUND THEN RAISE EXCEPTION 'avoirs_modifies'; END IF;

  UPDATE locations_actives
  SET data = (v_data - 'avertissement')
    || jsonb_build_object(
         'jourPaiement', v_jour,
         'dernierLoyerPaye', v_jour
       )
  WHERE id = p_bail_id;

  RETURN 'paye';
END;
$function$

CREATE OR REPLACE FUNCTION public.pret_national_contracter(p_montant numeric, p_duree_jours integer, p_type_pret text, p_building_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_nom text; v_pj public.personnages_donnees%ROWTYPE; v_taux numeric; v_total numeric; v_mensualite numeric; v_id text; v_solde numeric; v_arg numeric; v_liquide numeric;
BEGIN
 v_nom:=public.mon_personnage();
 IF v_nom IS NULL THEN RETURN jsonb_build_object('ok',false,'raison','non_authentifie'); END IF;
 SELECT * INTO v_pj FROM public.personnages_donnees WHERE name=v_nom FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'raison','personnage_absent'); END IF;
 IF p_montant IS NULL OR p_montant<>trunc(p_montant) OR p_montant<1000 OR p_montant>1000000
    OR p_duree_jours NOT IN (10,15,20,25,30)
    OR p_type_pret <> 'travaux' OR v_pj.country<>'republic'
    OR v_pj.current_building <> 'banque-nationale' THEN
  RETURN jsonb_build_object('ok',false,'raison','parametres_invalides');
 END IF;
 IF EXISTS(SELECT 1 FROM public.prets WHERE emprunteur=v_nom AND type_pret=p_type_pret AND statut='en_cours') THEN
  RETURN jsonb_build_object('ok',false,'raison','pret_deja_actif');
 END IF;
 SELECT solde INTO v_solde FROM public.comptes_bancaires WHERE personnage=v_nom AND banque='nationale' FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'raison','compte_national_absent'); END IF;
 v_taux:=public.taux_pret_nationale(v_pj.country);
 v_total:=round(p_montant*(1+v_taux/100));
 v_mensualite:=ceil(v_total/p_duree_jours);
 v_id:='pret-national-'||gen_random_uuid()::text;
 INSERT INTO public.prets(id,emprunteur,country,building_id,type_banque,type_pret,montant_initial,montant_restant,duree_jours,mensualite,jours_impayes,jour_dernier_prelevement,statut)
 VALUES(v_id,v_nom,v_pj.country,v_pj.current_building,'nationale',p_type_pret,p_montant,v_total,p_duree_jours,v_mensualite,0,(now() at time zone 'Europe/Paris')::date::text,'en_cours');
 INSERT INTO public.fonds_credits_uniques(acteur,source,reference,ordre,montant) VALUES(v_nom,'pret_national',v_id,'emprunter_construction',p_montant);
 UPDATE public.comptes_bancaires SET solde=solde+p_montant,updated_at=now() WHERE personnage=v_nom AND banque='nationale' RETURNING solde INTO v_solde;
 UPDATE public.personnages_donnees SET arg=COALESCE(arg,0)+p_montant,updated_at=now() WHERE name=v_nom RETURNING arg,COALESCE(liquide,0) INTO v_arg,v_liquide;
 RETURN jsonb_build_object('ok',true,'pret_id',v_id,'montant',p_montant,'solde_banque',v_solde,'arg',v_arg,'liquide',v_liquide);
END; $function$

CREATE OR REPLACE FUNCTION public.recherche_inscrire(p_entree jsonb, p_cible text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_moi text; v_cible text; v_id text; v_apres jsonb; v_n integer;
BEGIN
  IF p_entree IS NULL OR jsonb_typeof(p_entree) <> 'object' THEN
    RETURN jsonb_build_object('ok', false, 'raison', 'entree_invalide');
  END IF;

  v_moi := public.mon_personnage();
  IF v_moi IS NOT NULL THEN
    -- UN JOUEUR N'INSCRIT QUE SUR SA PROPRE FICHE. Condamner autrui est un pouvoir, et il a sa
    -- porte : justice_condamner, qui relit le poste de l'appelant.
    IF p_cible IS NOT NULL AND p_cible <> v_moi THEN
      RETURN jsonb_build_object('ok', false, 'raison', 'pas_ma_fiche');
    END IF;
    v_cible := v_moi;
  ELSE
    IF coalesce(btrim(coalesce(p_cible, '')), '') = '' THEN
      RETURN jsonb_build_object('ok', false, 'raison', 'cible_manquante');
    END IF;
    v_cible := p_cible;
  END IF;

  PERFORM set_config('rp.recherche_interne', 'on', true);

  -- IDEMPOTENCE PAR IDENTIFIANT, quand l'entree en porte un. C'est le cas du mandat d'arret des
  -- tracts calomnieux, dont le client verifiait deja l'absence avant de le refleter. Un crime
  -- ordinaire, lui, n'a pas d'identifiant : il peut etre commis deux fois, et doit s'inscrire
  -- deux fois.
  v_id := nullif(p_entree ->> 'id', '');
  IF v_id IS NOT NULL THEN
    SELECT count(*) INTO v_n FROM public.personnages_donnees d,
           jsonb_array_elements(CASE WHEN jsonb_typeof(d.recherche)='array'
                                     THEN d.recherche ELSE '[]'::jsonb END) e
     WHERE d.name = v_cible AND e ->> 'id' = v_id;
    IF v_n > 0 THEN
      SELECT coalesce(recherche, '[]'::jsonb) INTO v_apres
        FROM public.personnages_donnees WHERE name = v_cible;
      RETURN jsonb_build_object('ok', true, 'action', 'deja_inscrite',
                                'recherche', coalesce(v_apres, '[]'::jsonb));
    END IF;
  END IF;

  -- L'AJOUT EST ATOMIQUE : aucune relecture, donc aucune fenetre de perte.
  UPDATE public.personnages_donnees
     SET recherche = (CASE WHEN jsonb_typeof(recherche) = 'array'
                           THEN recherche ELSE '[]'::jsonb END) || jsonb_build_array(p_entree)
   WHERE name = v_cible
  RETURNING recherche INTO v_apres;
  PERFORM set_config('rp.recherche_interne', '', true);   -- la portee s'arrete ici
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'raison', 'personnage_introuvable');
  END IF;

  RETURN jsonb_build_object('ok', true, 'action', 'inscrite',
                            'recherche', coalesce(v_apres, '[]'::jsonb));
END; $function$

CREATE OR REPLACE FUNCTION public.terrain_compromis_acte(p_terrain_id text, p_acte text, p_patch jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_moi text; v_pays text; v_lu jsonb; v_etat jsonb; v_patch jsonb; v_final jsonb;
  v_cles text[]; v_k text;
BEGIN
  v_moi := public.mon_personnage();
  IF v_moi IS NULL THEN RETURN jsonb_build_object('ok', false, 'raison', 'acteur_non_authentifie'); END IF;
  IF p_acte NOT IN ('compromis_signer', 'compromis_pret_demander', 'compromis_transfert_proposer',
                    'compromis_transfert_accepter', 'achat_direct_deposer', 'achat_direct_accelerer') THEN
    RETURN jsonb_build_object('ok', false, 'raison', 'acte_inconnu');
  END IF;
  IF p_patch IS NULL OR jsonb_typeof(p_patch) <> 'object' THEN
    RETURN jsonb_build_object('ok', false, 'raison', 'patch_invalide');
  END IF;
  SELECT d.country INTO v_pays FROM public.personnages_donnees d WHERE d.name = v_moi LIMIT 1;

  -- LISTE DE CLES PAR ACTE (10 octobre 2026). Meme regle que `terrain_permis_acte` : un acte
  -- ne touche que les cles qu'il declare. Relevees sur les six chemins du navigateur.
  v_cles := CASE p_acte
    WHEN 'compromis_signer' THEN ARRAY['compromis', 'compromisPar', 'acompte',
                                        'compromisAt', 'compromisExpireAt', 'pretDemande', 'permis']
    WHEN 'compromis_pret_demander' THEN ARRAY['pretDemande']
    WHEN 'compromis_transfert_proposer' THEN ARRAY['transfertPropose', 'transfertProposePar']
    WHEN 'compromis_transfert_accepter' THEN ARRAY['compromisPar', 'transfertPropose',
                                        'transfertProposePar', 'permis', 'pretDemande']
    ELSE ARRAY['achatDirect'] END;
  FOR v_k IN SELECT jsonb_object_keys(p_patch) LOOP
    IF NOT (v_k = ANY (v_cles)) THEN
      RETURN jsonb_build_object('ok', false, 'raison', 'cle_hors_acte', 'cle', v_k);
    END IF;
  END LOOP;

  v_lu := public.terrain_etat_verrouiller_interne(p_terrain_id);
  v_etat := v_lu -> 'etat';
  -- LE GEL SUCCESSORAL EST LA MEME REGLE QUE DANS `terrain_proprietaire_muter`, lue en base.
  IF (v_lu ->> 'gele')::boolean THEN
    RETURN jsonb_build_object('ok', false, 'raison', 'terrain_gele');
  END IF;
  v_patch := p_patch;

  IF p_acte = 'compromis_signer' THEN
    -- LA REGLE EXISTAIT DEJA, cote serveur, pour le jumeau Helvetia : `signer_compromis_bien_helvetia`
    -- refuse « bien deja sous compromis ». Le chemin ordinaire ne la verifiait que dans l'ecran.
    IF coalesce((v_etat ->> 'compromis')::boolean, false)
       AND (v_etat ->> 'compromisPar') IS DISTINCT FROM v_moi THEN
      RETURN jsonb_build_object('ok', false, 'raison', 'deja_sous_compromis',
                                'detenteur', v_etat ->> 'compromisPar');
    END IF;
    -- LE DETENTEUR N'EST PLUS DICTE PAR LE NAVIGATEUR.
    v_patch := v_patch || jsonb_build_object('compromis', true, 'compromisPar', v_moi);

  ELSIF p_acte IN ('compromis_pret_demander', 'compromis_transfert_proposer') THEN
    IF coalesce((v_etat ->> 'compromis')::boolean, false) IS NOT TRUE
       OR (v_etat ->> 'compromisPar') IS DISTINCT FROM v_moi THEN
      RETURN jsonb_build_object('ok', false, 'raison', 'pas_mon_compromis');
    END IF;
    IF p_acte = 'compromis_transfert_proposer' THEN
      IF nullif(btrim(coalesce(v_patch ->> 'transfertPropose', '')), '') IS NULL THEN
        RETURN jsonb_build_object('ok', false, 'raison', 'destinataire_absent');
      END IF;
      IF (v_patch ->> 'transfertPropose') = v_moi THEN
        RETURN jsonb_build_object('ok', false, 'raison', 'transfert_a_soi_meme');
      END IF;
      v_patch := v_patch || jsonb_build_object('transfertProposePar', v_moi);
    END IF;

  ELSIF p_acte = 'compromis_transfert_accepter' THEN
    -- LA REGLE QUI N'EXISTAIT QUE DANS L'ECRAN. Sans elle, n'importe quel joueur connecte posait
    -- son nom dans `compromisPar` et reprenait le compromis d'un autre.
    IF (v_etat ->> 'transfertPropose') IS DISTINCT FROM v_moi THEN
      RETURN jsonb_build_object('ok', false, 'raison', 'transfert_non_propose');
    END IF;
    v_patch := v_patch || jsonb_build_object('compromisPar', v_moi,
      'transfertPropose', NULL, 'transfertProposePar', NULL);

  ELSIF p_acte = 'achat_direct_deposer' THEN
    IF coalesce((v_etat ->> 'compromis')::boolean, false)
       OR ((v_etat -> 'achatDirect') IS NOT NULL
           AND (v_etat -> 'achatDirect' ->> 'demandeur') IS DISTINCT FROM v_moi) THEN
      RETURN jsonb_build_object('ok', false, 'raison', 'terrain_indisponible');
    END IF;
    IF jsonb_typeof(v_patch -> 'achatDirect') <> 'object' THEN
      RETURN jsonb_build_object('ok', false, 'raison', 'achat_direct_absent');
    END IF;
    v_patch := jsonb_set(v_patch, '{achatDirect,demandeur}', to_jsonb(v_moi));

  ELSIF p_acte = 'achat_direct_accelerer' THEN
    -- REGLE RECOPIEE MOT POUR MOT DU CLIENT :
    --   if (!ts.achatDirect || ts.achatDirect.demandeur !== state.char?.name)
    IF (v_etat -> 'achatDirect') IS NULL
       OR (v_etat -> 'achatDirect' ->> 'demandeur') IS DISTINCT FROM v_moi THEN
      RETURN jsonb_build_object('ok', false, 'raison', 'pas_mon_achat_direct');
    END IF;
    v_patch := jsonb_set(v_patch, '{achatDirect,demandeur}', to_jsonb(v_moi));
  END IF;

  v_final := public.terrain_etat_fusionner_interne(p_terrain_id, v_patch, v_pays);
  RETURN jsonb_build_object('ok', true, 'acte', p_acte, 'etat', v_final);
END; $function$

CREATE OR REPLACE FUNCTION public.terrain_lots_acte(p_terrain_id text, p_acte text, p_lots jsonb DEFAULT NULL::jsonb, p_retirer text[] DEFAULT NULL::text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_moi text; v_pays text; v_lu jsonb; v_etat jsonb; v_lots jsonb; v_final jsonb;
  v_neuf jsonb; v_lot jsonb; v_remplacant jsonb; v_id text; v_i integer; v_n integer := 0;
BEGIN
  v_moi := public.mon_personnage();
  IF v_moi IS NULL THEN RETURN jsonb_build_object('ok', false, 'raison', 'acteur_non_authentifie'); END IF;
  IF p_acte NOT IN ('lot_ajouter', 'lot_fusion_proposer', 'lot_fusion_accepter',
                    'lot_fusion_refuser', 'lot_louer', 'lot_bail_libere') THEN
    RETURN jsonb_build_object('ok', false, 'raison', 'acte_inconnu');
  END IF;
  IF p_lots IS NOT NULL AND jsonb_typeof(p_lots) <> 'array' THEN
    RETURN jsonb_build_object('ok', false, 'raison', 'lots_invalides');
  END IF;
  IF coalesce(jsonb_array_length(coalesce(p_lots, '[]'::jsonb)), 0) = 0
     AND coalesce(array_length(p_retirer, 1), 0) = 0 THEN
    RETURN jsonb_build_object('ok', false, 'raison', 'rien_a_ecrire');
  END IF;
  SELECT d.country INTO v_pays FROM public.personnages_donnees d WHERE d.name = v_moi LIMIT 1;

  v_lu := public.terrain_etat_verrouiller_interne(p_terrain_id);
  v_etat := v_lu -> 'etat';
  IF (v_lu ->> 'gele')::boolean THEN
    RETURN jsonb_build_object('ok', false, 'raison', 'terrain_gele');
  END IF;
  v_lots := coalesce(v_etat -> 'subdivisions', '[]'::jsonb);
  IF jsonb_typeof(v_lots) <> 'array' THEN v_lots := '[]'::jsonb; END IF;

  -- AUTORITE PAR ACTE. Les deux actes du proprietaire passent par le jumeau SQL de `estTitulaire`,
  -- qui reconnait `pj:<nom>` comme la chaine nue. Les autres sont le fait du locataire ou du
  -- visiteur : les ecrans ne leur demandaient rien d'autre que de concerner leur propre lot, et
  -- c'est ce que la porte verifie lot par lot.
  IF p_acte IN ('lot_ajouter', 'lot_fusion_proposer') THEN
    IF NOT public.titulaire_est_moi(v_etat ->> 'proprietaire') THEN
      RETURN jsonb_build_object('ok', false, 'raison', 'pas_proprietaire');
    END IF;
  ELSIF p_acte IN ('lot_fusion_accepter', 'lot_fusion_refuser') THEN
    FOR v_lot IN SELECT * FROM jsonb_array_elements(coalesce(p_lots, '[]'::jsonb)) LOOP
      v_id := v_lot ->> 'id';
      IF NOT EXISTS (
        SELECT 1 FROM jsonb_array_elements(v_lots) e
         WHERE (e.value ->> 'id') = v_id
           AND (e.value -> 'propositionAgrandissement') IS NOT NULL
           AND public.titulaire_est_moi(e.value ->> 'locataire')) THEN
        RETURN jsonb_build_object('ok', false, 'raison', 'aucune_proposition_sur_mon_lot', 'lot', v_id);
      END IF;
    END LOOP;
  ELSIF p_acte = 'lot_louer' THEN
    -- Le bail est pris ATOMIQUEMENT ailleurs (`locations_actives`, cle primaire). Cette ecriture
    -- n'est que le miroir transitoire que le cron des loyers lit encore : la porte verifie donc
    -- seulement que le locataire pose est bien l'appelant.
    FOR v_lot IN SELECT * FROM jsonb_array_elements(coalesce(p_lots, '[]'::jsonb)) LOOP
      IF NOT public.titulaire_est_moi(v_lot ->> 'locataire') THEN
        RETURN jsonb_build_object('ok', false, 'raison', 'pas_mon_bail', 'lot', v_lot ->> 'id');
      END IF;
    END LOOP;
  ELSIF p_acte = 'lot_bail_libere' THEN
    -- Fin de bail : le miroir se vide. Le champ pose doit etre NUL -- on ne liberera jamais un lot
    -- en y INSTALLANT quelqu'un.
    FOR v_lot IN SELECT * FROM jsonb_array_elements(coalesce(p_lots, '[]'::jsonb)) LOOP
      IF nullif(btrim(coalesce(v_lot ->> 'locataire', '')), '') IS NOT NULL THEN
        RETURN jsonb_build_object('ok', false, 'raison', 'liberation_qui_installe', 'lot', v_lot ->> 'id');
      END IF;
    END LOOP;
  END IF;

  -- FUSION PAR IDENTIFIANT DE LOT. Un lot dont l'identifiant existe est REMPLACE ; sinon il est
  -- ajoute. Les identifiants de `p_retirer` disparaissent. Le reste du tableau n'est pas touche.
  v_neuf := '[]'::jsonb;
  FOR v_i IN 0 .. greatest(0, jsonb_array_length(v_lots) - 1) LOOP
    v_lot := v_lots -> v_i;
    v_id := v_lot ->> 'id';
    IF v_id IS NOT NULL AND p_retirer IS NOT NULL AND v_id = ANY (p_retirer) THEN
      v_n := v_n + 1;
      CONTINUE;
    END IF;
    IF v_id IS NOT NULL THEN
      v_remplacant := NULL;
      SELECT e.value INTO v_remplacant FROM jsonb_array_elements(coalesce(p_lots, '[]'::jsonb)) e
       WHERE (e.value ->> 'id') = v_id LIMIT 1;
      IF v_remplacant IS NOT NULL THEN v_lot := v_remplacant; END IF;
    END IF;
    v_neuf := v_neuf || jsonb_build_array(v_lot);
  END LOOP;
  -- Les lots envoyes qui n'existaient pas encore sont AJOUTES, dans l'ordre d'arrivee.
  FOR v_lot IN SELECT * FROM jsonb_array_elements(coalesce(p_lots, '[]'::jsonb)) LOOP
    IF NOT EXISTS (SELECT 1 FROM jsonb_array_elements(v_neuf) e
                    WHERE (e.value ->> 'id') = (v_lot ->> 'id')) THEN
      v_neuf := v_neuf || jsonb_build_array(v_lot);
    END IF;
  END LOOP;

  v_final := public.terrain_etat_fusionner_interne(p_terrain_id,
               jsonb_build_object('subdivisions', v_neuf), v_pays);
  RETURN jsonb_build_object('ok', true, 'acte', p_acte, 'etat', v_final,
    'lots', v_neuf, 'retires', v_n);
END; $function$

CREATE OR REPLACE FUNCTION public.terrain_negociation_conclure(p_terrain text, p_occupation text, p_montant integer, p_requete uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE acteur text:=public.mon_personnage();p record;r record;c jsonb;e jsonb;cle text;solde numeric;
 paiement jsonb;resultat jsonb;taux integer;jet integer;accepte boolean;bonus integer:=0;argent integer;
BEGIN
 IF acteur IS NULL THEN RETURN jsonb_build_object('ok',false,'raison','acteur_non_authentifie'); END IF;
 IF p_requete IS NULL OR p_montant IS NULL OR p_montant<1 OR nullif(p_occupation,'') IS NULL THEN
  RETURN jsonb_build_object('ok',false,'raison','requete_invalide'); END IF;
 SELECT * INTO p FROM public.personnages_donnees WHERE name=acteur FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'raison','personnage_introuvable'); END IF;
 SELECT n.* INTO r FROM public.terrain_negociations_recus n WHERE n.acteur=p.id AND n.requete=p_requete;
 IF FOUND THEN
  IF r.terrain IS DISTINCT FROM p.country||'_'||p_terrain OR r.occupation IS DISTINCT FROM p_occupation OR r.montant<>p_montant THEN
   RETURN jsonb_build_object('ok',false,'raison','requete_reutilisee'); END IF;
  resultat:=r.resultat||jsonb_build_object('rejeu',true);
  SELECT public.terrain_etat_lire(data) INTO e FROM public.terrains_etat WHERE id=r.terrain;
 ELSE
  c:=public.terrain_negociation_preparer(p_terrain);
  IF c->>'ok' IS DISTINCT FROM 'true' THEN RETURN c; END IF;
  IF c->>'occupation' IS DISTINCT FROM p_occupation THEN RETURN jsonb_build_object('ok',false,'raison','occupation_modifiee','etat',c->'etat'); END IF;
  IF p_montant<(c->>'minimum')::numeric THEN RETURN jsonb_build_object('ok',false,'raison','offre_trop_faible','minimum',c->'minimum','dernierRefus',c->'dernierRefus'); END IF;
  SELECT coalesce(cb.solde,0) INTO solde FROM public.comptes_bancaires cb WHERE cb.personnage=acteur AND cb.banque='nationale' FOR UPDATE;
  IF coalesce(p.liquide,0)+coalesce(solde,0)<p_montant THEN RETURN jsonb_build_object('ok',false,'raison','fonds_insuffisants'); END IF;
  paiement:=public.payer_ordre(acteur,'negocier_squatteurs',1,0);
  IF paiement->>'ok' IS DISTINCT FROM 'true' THEN RETURN paiement; END IF;
  argent:=CASE WHEN p_montant>=4000 THEN 20 WHEN p_montant>=1000 THEN floor(8+(p_montant-1000)::numeric*4/1000)
   WHEN p_montant>=500 THEN floor(5+(p_montant-500)::numeric*3/500) ELSE floor(p_montant::numeric/100) END;
  taux:=greatest(5,least(90,floor((c->>'baseTaux')::numeric+argent+.5)::integer));
  jet:=public.terrain_negociation_jet_interne();accepte:=jet<=taux;e:=c->'etat';cle:=p.country||'_'||p_terrain;
  IF accepte THEN
   IF public.helvetia_debiter_fonds_ordinaires(acteur,p_montant) IS NOT TRUE THEN RAISE EXCEPTION 'paiement_non_confirme'; END IF;
   IF e->>'pnj'='squatter_cool' THEN
    UPDATE public.personnages_donnees SET moral=least(100,coalesce(moral,50)+1) WHERE id=p.id RETURNING moral-coalesce(p.moral,50) INTO bonus;
   END IF;
   e:=public.terrain_etat_fusionner_interne(cle,'{"pnj":null,"pnjData":null,"occupationScellee":true}'::jsonb,p.country);
  ELSE
   INSERT INTO public.terrain_negociations_refus VALUES(p.id,cle,p_occupation,p_montant)
    ON CONFLICT ON CONSTRAINT terrain_negociations_refus_pkey DO UPDATE SET montant=excluded.montant;
  END IF;
  resultat:=jsonb_build_object('ok',true,'accepte',accepte,'pnj',c->'etat'->>'pnj','montant',p_montant,'taux',taux,'jet',jet,'bonusMoral',bonus);
  INSERT INTO public.terrain_negociations_recus(acteur,requete,terrain,occupation,montant,resultat) VALUES(p.id,p_requete,cle,p_occupation,p_montant,resultat);
 END IF;
 SELECT jsonb_build_object('pa',d.pa,'arg',d.arg,'liquide',d.liquide,'moral',d.moral,
  'solde_national',coalesce((SELECT cb.solde FROM public.comptes_bancaires cb WHERE cb.personnage=acteur AND cb.banque='nationale'),0))
  INTO paiement FROM public.personnages_donnees d WHERE id=p.id;
 RETURN resultat||jsonb_build_object('etat',e,'paiement',paiement);
END;$function$

CREATE OR REPLACE FUNCTION public.terrain_negociation_preparer(p_terrain text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE acteur text:=public.mon_personnage();p record;t record;e jsonb;revision text;dernier integer;
 cha numeric;social numeric;bonus integer;org record;m jsonb;grade integer;
BEGIN
 IF acteur IS NULL THEN RETURN jsonb_build_object('ok',false,'raison','acteur_non_authentifie'); END IF;
 SELECT * INTO p FROM public.personnages_donnees WHERE name=acteur FOR UPDATE;
 IF NOT FOUND OR p.current_building IS DISTINCT FROM p_terrain OR p_terrain NOT LIKE 'terrain-a-batir%' THEN
  RETURN jsonb_build_object('ok',false,'raison','pas_sur_place'); END IF;
 SELECT * INTO t FROM public.terrains_etat WHERE id=p.country||'_'||p_terrain
  AND country=p.country AND building_id=p_terrain FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'raison','terrain_introuvable'); END IF;
 e:=public.terrain_etat_lire(t.data);
 IF e IS NULL OR e->>'city' IS DISTINCT FROM p.current_city THEN RETURN jsonb_build_object('ok',false,'raison','terrain_incoherent'); END IF;
 IF coalesce(e->>'succession_gel','')<>'' THEN RETURN jsonb_build_object('ok',false,'raison','terrain_gele','etat',e); END IF;
 IF coalesce(e->>'policeAppellee','')<>'' OR coalesce((e->>'enqueteJusqua')::numeric,0)>extract(epoch FROM clock_timestamp())*1000 THEN
  RETURN jsonb_build_object('ok',false,'raison','intervention_en_cours','etat',e); END IF;
 IF coalesce(e->>'pnj','') NOT IN ('squatter_cool','squatter_agr') THEN
  RETURN jsonb_build_object('ok',false,'raison','aucun_squatteur','etat',e); END IF;
 revision:=coalesce(e->>'dateGeneration','historique')||':'||(e->>'pnj');
 SELECT n.montant INTO dernier FROM public.terrain_negociations_refus n WHERE n.acteur=p.id AND n.terrain=t.id AND n.occupation=revision;
 SELECT avg(v) INTO cha FROM (
  SELECT coalesce((p.stats->>'CHA')::numeric,8) v
  UNION ALL SELECT mb.car_cha::numeric
   FROM public.pnj_membres mb JOIN public.pnj_employes_metier em ON em.pnj_id=mb.id
   WHERE mb.proprietaire_pj=acteur AND mb.leader_pj=acteur AND mb.statut='actif'
 ) valeurs;
 cha:=cha-CASE WHEN p.excommunie IS NOT NULL AND p.excommunie<>'null'::jsonb THEN 2 ELSE 0 END;
 IF p.stats_affaiblies ? 'CHA' THEN cha:=greatest(1,floor(cha*greatest(0,least(1,coalesce(p.hp,0)::numeric/100))+.5));
 ELSE cha:=floor(cha+.5); END IF;
 IF p.country='republic' THEN
  SELECT (data->>'social')::numeric INTO social FROM public.indices_villes WHERE id=p.country||'_'||p.current_city;
  social:=coalesce(social,45);
 ELSE social:=CASE p.country WHEN 'narco' THEN 25 WHEN 'soviet' THEN 35 WHEN 'khalija' THEN 40 ELSE 45 END; END IF;
 bonus:=0;
 FOR org IN SELECT data::jsonb d FROM public.organisations LOOP
  SELECT v INTO m FROM jsonb_array_elements(coalesce(org.d->'membres','[]'::jsonb)) v WHERE v->>'nom'=acteur LIMIT 1;
  IF m IS NULL THEN CONTINUE; END IF;
  grade:=coalesce((m->>'gradeIdx')::integer,0);
  bonus:=bonus+CASE org.d->>'type'
   WHEN 'economique' THEN CASE WHEN grade>=3 THEN 30 WHEN grade>=2 THEN 20 WHEN grade>=1 THEN 10 ELSE 0 END
   WHEN 'syndicale' THEN CASE WHEN grade>=2 THEN 25 WHEN grade>=1 THEN 15 ELSE 0 END ELSE 0 END;
 END LOOP;
 RETURN jsonb_build_object('ok',true,'etat',e,'occupation',revision,'dernierRefus',dernier,
  'minimum',greatest(CASE WHEN e->>'pnj'='squatter_agr' THEN 500 ELSE 1 END,coalesce(dernier::numeric+1,1)),
  'baseTaux',50+2*(cha-13)+(social-50)/5+bonus);
END;$function$

CREATE OR REPLACE FUNCTION public.terrain_occupation_lire(p_terrain text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE acteur text:=public.mon_personnage();p record;t record;e jsonb;nouvelle boolean;occupation text;
BEGIN
 IF acteur IS NULL THEN RETURN jsonb_build_object('ok',false,'raison','acteur_non_authentifie'); END IF;
 SELECT id,country,current_city,current_building INTO p FROM public.personnages_donnees WHERE name=acteur FOR UPDATE;
 IF NOT FOUND OR p.current_building IS DISTINCT FROM p_terrain OR p_terrain NOT LIKE 'terrain-a-batir%' THEN
  RETURN jsonb_build_object('ok',false,'raison','pas_sur_place'); END IF;
 SELECT * INTO t FROM public.terrains_etat WHERE id=p.country||'_'||p_terrain AND country=p.country
  AND building_id=p_terrain FOR UPDATE;
 IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'raison','terrain_introuvable'); END IF;
 e:=public.terrain_etat_lire(t.data);
 IF e IS NULL OR e->>'city' IS DISTINCT FROM p.current_city THEN RETURN jsonb_build_object('ok',false,'raison','terrain_incoherent'); END IF;
 nouvelle:=NOT EXISTS(SELECT 1 FROM public.terrain_visites_actives WHERE terrain_id=t.id);
 IF nouvelle AND NOT coalesce((e->>'occupationScellee')::boolean,false)
  AND nullif(e->>'proprietaire','') IS NULL AND NOT coalesce((e->>'compromis')::boolean,false)
  AND coalesce(e->>'succession_gel','')=''
  AND coalesce(e->>'policeAppellee','')=''
  AND coalesce((e->>'enqueteJusqua')::numeric,0)<=extract(epoch FROM clock_timestamp())*1000 THEN
  -- Conserver une presence historique a sa premiere adoption, sans la reinterpreter.
  IF coalesce((e->>'occupationInitialisee')::boolean,false) OR NOT (e ? 'pnj') THEN
   occupation:=public.terrain_occupation_tirer_interne();
   e:=public.terrain_etat_fusionner_interne(t.id,jsonb_build_object('pnj',occupation,'pnjData',NULL,
    'occupationInitialisee',true,'dateGeneration',floor(extract(epoch FROM clock_timestamp())*1000)),p.country);
  ELSE
   e:=public.terrain_etat_fusionner_interne(t.id,'{"occupationInitialisee":true}',p.country);
  END IF;
 END IF;
 IF nullif(e->>'proprietaire','') IS NOT NULL OR coalesce((e->>'compromis')::boolean,false) THEN
  e:=public.terrain_etat_fusionner_interne(t.id,'{"occupationScellee":true}',p.country);
 END IF;
 INSERT INTO public.terrain_visites_actives VALUES(p.id,t.id) ON CONFLICT DO NOTHING;
 RETURN jsonb_build_object('ok',true,'etat',e);
END;$function$

CREATE OR REPLACE FUNCTION public.terrain_proprietaire_muter(p_terrain_id text, p_titre text, p_patch jsonb, p_reference text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_moi text; v_data jsonb; v_cle text; v_prix numeric; v_n integer; v_nouveau text;
BEGIN
  IF p_titre NOT IN ('compromis','achat_direct','recompense_quete','serveur') THEN
    RETURN jsonb_build_object('ok', false, 'raison', 'titre_inconnu');
  END IF;
  IF p_patch IS NULL OR jsonb_typeof(p_patch) <> 'object' THEN
    RETURN jsonb_build_object('ok', false, 'raison', 'patch_invalide');
  END IF;

  v_moi := public.mon_personnage();
  IF p_titre = 'serveur' THEN
    IF v_moi IS NOT NULL THEN
      RETURN jsonb_build_object('ok', false, 'raison', 'titre_reserve_au_serveur');
    END IF;
  ELSIF v_moi IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'raison', 'acteur_non_authentifie');
  END IF;

  SELECT t.id, t.data::jsonb INTO v_cle, v_data FROM public.terrains_etat t
   WHERE t.id = p_terrain_id OR t.building_id = p_terrain_id
   ORDER BY (t.id = p_terrain_id) DESC LIMIT 1 FOR UPDATE;
  IF v_cle IS NULL THEN RETURN jsonb_build_object('ok', false, 'raison', 'terrain_introuvable'); END IF;
  v_data := coalesce(v_data, '{}'::jsonb);

  -- LE GEL SUCCESSORAL EST REFUSE AU SERVEUR, plus seulement dans le navigateur.
  IF coalesce(v_data ->> 'succession_gel', '') <> '' THEN
    RETURN jsonb_build_object('ok', false, 'raison', 'terrain_gele');
  END IF;

  IF p_titre = 'compromis' THEN
    IF coalesce((v_data ->> 'compromis')::boolean, false) IS NOT TRUE
       OR (v_data ->> 'compromisPar') IS DISTINCT FROM v_moi THEN
      RETURN jsonb_build_object('ok', false, 'raison', 'pas_mon_compromis');
    END IF;
  ELSIF p_titre = 'achat_direct' THEN
    IF (v_data -> 'achatDirect' ->> 'demandeur') IS DISTINCT FROM v_moi THEN
      RETURN jsonb_build_object('ok', false, 'raison', 'pas_mon_achat_direct');
    END IF;
  ELSIF p_titre = 'recompense_quete' THEN
    IF NOT EXISTS (SELECT 1 FROM public.quetes_actives q
                    WHERE q.id = p_reference AND q.statut = 'resolue' AND q.resolu_par = v_moi) THEN
      RETURN jsonb_build_object('ok', false, 'raison', 'pas_ma_quete');
    END IF;
  END IF;

  -- LA FUSION SE FAIT SUR L'ETAT REEL, SOUS VERROU : un patch partiel n'efface plus rien, et un
  -- cache client perime ne peut plus ecraser le serveur.
  v_data := v_data || p_patch;
  v_nouveau := nullif(v_data ->> 'proprietaire', '');

  UPDATE public.terrains_etat
     SET data = v_data::text, proprietaire = v_nouveau, updated_at = now()
   WHERE id = v_cle;

  -- L'HISTORIQUE PUBLIC DE LA VENTE, DANS LA MEME TRANSACTION. Son identifiant est DATE et non
  -- horodate a la milliseconde : un rejeu le meme jour sur le meme terrain ne cree pas une seconde
  -- ligne, et le registre ne peut plus acter une vente qui n'a pas eu lieu.
  v_prix := nullif(p_patch ->> 'valeur_totale', '')::numeric;
  IF p_titre IN ('compromis','achat_direct') AND v_prix IS NOT NULL AND v_nouveau IS NOT NULL THEN
    INSERT INTO public.terrains_historique_ventes (id, country, building_id, proprietaire, prix)
    SELECT 'vente-' || t.building_id || '-' || to_char(now() AT TIME ZONE 'UTC','YYYYMMDD')
             || '-' || v_nouveau,
           t.country, t.building_id, v_nouveau, v_prix
      FROM public.terrains_etat t WHERE t.id = v_cle
    ON CONFLICT (id) DO NOTHING;
    GET DIAGNOSTICS v_n = ROW_COUNT;
  ELSE
    v_n := 0;
  END IF;

  RETURN jsonb_build_object('ok', true, 'titre', p_titre, 'cle', v_cle,
    'proprietaire', v_nouveau, 'vente_consignee', v_n = 1, 'etat', v_data);
END; $function$

CREATE OR REPLACE FUNCTION public.terrain_reamenagement_poser(p_terrain_id text, p_chantier jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_moi text; v_pays text; v_lu jsonb; v_etat jsonb; v_final jsonb;
BEGIN
  v_moi := public.mon_personnage();
  IF v_moi IS NULL THEN RETURN jsonb_build_object('ok', false, 'raison', 'acteur_non_authentifie'); END IF;
  IF p_chantier IS NULL OR jsonb_typeof(p_chantier) <> 'object' THEN
    RETURN jsonb_build_object('ok', false, 'raison', 'chantier_absent');
  END IF;
  SELECT d.country INTO v_pays FROM public.personnages_donnees d WHERE d.name = v_moi LIMIT 1;

  v_lu := public.terrain_etat_verrouiller_interne(p_terrain_id);
  v_etat := v_lu -> 'etat';
  IF (v_lu ->> 'gele')::boolean THEN
    RETURN jsonb_build_object('ok', false, 'raison', 'terrain_gele');
  END IF;
  -- LA REGLE DES DEUX ECRANS DE RECONFIGURATION, lue en base :
  --   if (!estTitulaire(ts.proprietaire)) « Vous n'etes pas proprietaire de ce batiment. »
  IF NOT public.titulaire_est_moi(v_etat ->> 'proprietaire') THEN
    RETURN jsonb_build_object('ok', false, 'raison', 'pas_proprietaire');
  END IF;
  -- LISTE DE CLES, en dur : cette porte n'ecrit QUE son propre chantier. Elle ne peut donc pas
  -- effacer `chantier`, `permis`, `subdivisions` ni le compromis, meme appelee par un client
  -- modifie ou par un ecran reste ouvert pendant la nuit du cron.
  v_final := public.terrain_etat_fusionner_interne(p_terrain_id,
               jsonb_build_object('chantierReamenagement', p_chantier), v_pays);
  RETURN jsonb_build_object('ok', true, 'etat', v_final);
END; $function$
